import { describe, expect, it } from "vitest";
import { signRequest } from "./signing";

/**
 * Vectors generated by CALLING THE REAL GO `merchantauth.Sign`/`Verify`
 * functions (`services/voucher/internal/merchantauth/signing.go`), not by
 * re-deriving them from this file — a scratch Go program (module
 * `github.com/yourtal/services/voucher/scratchsigvector`, replacing the real
 * module in, outside this repo, per TASKS.md 8.3.b) imported the package
 * directly, signed each case below, and asserted `Verify` accepted its own
 * output before printing it. `body` is base64 here only so this file has no
 * embedded raw JSON to keep byte-exact by hand; `signRequest` is fed the
 * decoded bytes below, exactly as `Sign` was.
 *
 * This is the proof that this TypeScript implementation is byte-identical
 * to the Go verifier a brand's requests are actually checked against — a
 * mismatch here means every real integration using this SDK gets a 401.
 */
const SECRET = "a merchant's shared secret, 32 bytes minimum";
const TIMESTAMP = new Date("2026-09-27T10:30:00.000Z");

interface Vector {
  name: string;
  keyId: string;
  method: string;
  pathAndQuery: string;
  idempotencyKey: string;
  bodyBase64: string;
  header: string;
}

const VECTORS: Vector[] = [
  {
    name: "authorize, no query, with idempotency key",
    keyId: "key_live_1",
    method: "POST",
    pathAndQuery: "/v1/vouchers/authorize",
    idempotencyKey: "idem-authorize-0001",
    bodyBase64:
      "eyJjb2RlIjoiQUJDRDEyMzRFRkdINTY3OEsiLCJhbW91bnRfbWlub3IiOjMwMDAsImN1cnJlbmN5IjoiQVVEIiwibWVyY2hhbnRfb3JkZXJfcmVmIjoiT1JERVItMSIsIm9yZGVyX3RvdGFsX21pbm9yIjo1MDAwfQ==",
    header:
      "t=1790505000,k=key_live_1,v1=7e3aff4db0d9542fed86cc106b54f553ef3edd4103de3bc173cd87834a3b8f84",
  },
  {
    name: "capture",
    keyId: "key_live_1",
    method: "POST",
    pathAndQuery: "/v1/vouchers/capture",
    idempotencyKey: "idem-capture-0001",
    bodyBase64: "eyJhdXRob3JpemF0aW9uX2lkIjoiYXV0aF9hYmMxMjMiLCJmaW5hbF9hbW91bnRfbWlub3IiOjMwMDB9",
    header:
      "t=1790505000,k=key_live_1,v1=b52be86b5441e617adb8a224a0238b15a19cb0603c0cf72ceb06ed97bbfa9bf7",
  },
  {
    name: "void",
    keyId: "key_live_1",
    method: "POST",
    pathAndQuery: "/v1/vouchers/void",
    idempotencyKey: "idem-void-0001",
    bodyBase64: "eyJhdXRob3JpemF0aW9uX2lkIjoiYXV0aF9hYmMxMjMifQ==",
    header:
      "t=1790505000,k=key_live_1,v1=827b4bef73d5e6de00e2aa165c8d4ea133a1041962891fc4ad1e479addb38908",
  },
  {
    name: "refund",
    keyId: "key_live_1",
    method: "POST",
    pathAndQuery: "/v1/vouchers/refund",
    idempotencyKey: "idem-refund-0001",
    bodyBase64:
      "eyJyZWNlaXB0X2lkIjoicmNwdF94eXo3ODkiLCJhbW91bnRfbWlub3IiOjEwMDAsInJlYXNvbiI6ImN1c3RvbWVyX3JlcXVlc3QiLCJyZWZ1bmRfcmVmIjoiUkVGVU5ELTEifQ==",
    header:
      "t=1790505000,k=key_live_1,v1=b47523acb5be5a9aa1fd8b837fa6be16d5c205794c3d8821baa69acfd28d6e33",
  },
  {
    name: "no idempotency key",
    keyId: "key_live_2",
    method: "POST",
    pathAndQuery: "/v1/vouchers/authorize",
    idempotencyKey: "",
    bodyBase64: "eyJjb2RlIjoiWlpaWjk5OTkiLCJhbW91bnRfbWlub3IiOjEsImN1cnJlbmN5IjoiSURSIn0=",
    header:
      "t=1790505000,k=key_live_2,v1=ef6821bebe8dd5085512664aed644b68c4ebfe6658738347c02e90d950137f16",
  },
  {
    name: "empty body with query string",
    keyId: "key_live_1",
    method: "GET",
    pathAndQuery: "/v1/vouchers/authorize?debug=1",
    idempotencyKey: "idem-empty-0001",
    bodyBase64: "",
    header:
      "t=1790505000,k=key_live_1,v1=ea3a609309426e7c1b920decd0a73f9540963a05d10c77c2a34575f45b2cca73",
  },
];

describe("signRequest — byte-identical to the Go merchantauth verifier", () => {
  for (const vector of VECTORS) {
    it(vector.name, () => {
      const body = Buffer.from(vector.bodyBase64, "base64");
      const header = signRequest({
        secret: SECRET,
        keyId: vector.keyId,
        method: vector.method,
        pathAndQuery: vector.pathAndQuery,
        idempotencyKey: vector.idempotencyKey,
        body,
        timestamp: TIMESTAMP,
      });
      expect(header).toBe(vector.header);
    });
  }

  it("lower-cases an upper-cased method the same way Go's strings.ToUpper does", () => {
    const vector = VECTORS[0];
    if (!vector) throw new Error("vectors must not be empty");
    const body = Buffer.from(vector.bodyBase64, "base64");
    const header = signRequest({
      secret: SECRET,
      keyId: vector.keyId,
      method: "post",
      pathAndQuery: vector.pathAndQuery,
      idempotencyKey: vector.idempotencyKey,
      body,
      timestamp: TIMESTAMP,
    });
    expect(header).toBe(vector.header);
  });

  it("produces a different signature for a different body (amount tampering fails closed)", () => {
    const vector = VECTORS[0];
    if (!vector) throw new Error("vectors must not be empty");
    const tamperedBody = Buffer.from(vector.bodyBase64, "base64");
    tamperedBody[0] = (tamperedBody[0] ?? 0) ^ 0xff; // flip a byte; only needs to differ
    const header = signRequest({
      secret: SECRET,
      keyId: vector.keyId,
      method: vector.method,
      pathAndQuery: vector.pathAndQuery,
      idempotencyKey: vector.idempotencyKey,
      body: tamperedBody,
      timestamp: TIMESTAMP,
    });
    expect(header).not.toBe(vector.header);
  });
});
